"""Google Gemini AI Service for resume validation, recruiter summaries, and interview guidance.

Provides transparent candidate evaluation using Google Gemini while gracefully falling back
when unconfigured or on network/rate-limit issues.
"""

from __future__ import annotations

import json
import logging
import os
import re
from typing import Any

from pydantic import BaseModel, Field

logger = logging.getLogger(__name__)


class GeminiValidationResult(BaseModel):
    """Structured AI validation and interview guidance generated by Gemini."""

    status: str = Field(
        ...,
        description="Status code: 'success', 'unconfigured', or 'error'",
    )
    validation_score: int | None = Field(
        default=None,
        description="Score (0-100) assessing resume depth, project authenticity, and relevance",
    )
    executive_summary: str = Field(
        ...,
        description="Executive recruiter summary detailing candidate fit against the job description",
    )
    strengths: list[str] = Field(
        default_factory=list,
        description="Key demonstrated strengths directly applicable to the job requirements",
    )
    risks_or_concerns: list[str] = Field(
        default_factory=list,
        description="Identified technical gaps, vague assertions, or areas needing validation",
    )
    interview_questions: list[str] = Field(
        default_factory=list,
        description="Targeted technical questions to probe during interview loops",
    )
    authenticity_assessment: str = Field(
        default="",
        description="Assessment of project credibility, career continuity, and technical substance",
    )
    model_used: str | None = Field(
        default=None,
        description="The Gemini model identifier used for evaluation",
    )
    error_message: str | None = Field(
        default=None,
        description="Error detail when status is 'error'",
    )


def get_gemini_api_key() -> str | None:
    """Return configured Gemini API key, checking GEMINI_API_KEY then GOOGLE_API_KEY."""
    key = os.getenv("GEMINI_API_KEY") or os.getenv("GOOGLE_API_KEY")
    if key and key.strip():
        return key.strip()
    return None


def is_gemini_available() -> bool:
    """Check whether Gemini is configured with a valid API key."""
    return get_gemini_api_key() is not None


def _clean_json_markdown(text: str) -> str:
    """Extract raw JSON text from markdown code fences if present."""
    text = text.strip()
    match = re.search(r"```(?:json)?\s*([\s\S]*?)\s*```", text)
    if match:
        return match.group(1).strip()
    return text


def validate_candidate_with_gemini(
    job_description: str,
    candidate_name: str,
    candidate_text: str = "",
    matched_skills: list[str] | None = None,
    missing_skills: list[str] | None = None,
    model_name: str | None = None,
) -> GeminiValidationResult:
    """Validate a candidate's resume against a target job description using Google Gemini.

    Args:
        job_description: The full text of the target job posting.
        candidate_name: Filename or identifier of the candidate.
        candidate_text: Extracted plain text of candidate resume (truncated to 10k chars).
        matched_skills: List of technical skills already confirmed matched by NLP parser.
        missing_skills: List of required/preferred skills not detected by NLP parser.
        model_name: Optional override for Gemini model (defaults to gemini-2.5-flash).

    Returns:
        GeminiValidationResult containing structured feedback, interview questions, and validation scores.
    """
    api_key = get_gemini_api_key()
    if not api_key:
        return GeminiValidationResult(
            status="unconfigured",
            validation_score=None,
            executive_summary=(
                "Gemini AI validation is currently unconfigured. Set the GEMINI_API_KEY "
                "environment variable in Vercel or your local environment to enable AI resume "
                "validation, fit analysis, and tailored interview questions."
            ),
            strengths=matched_skills[:4] if matched_skills else [],
            risks_or_concerns=(
                [f"Missing required skills: {', '.join(missing_skills[:3])}"]
                if missing_skills
                else []
            ),
            interview_questions=[],
            authenticity_assessment="AI validation unavailable without an active Gemini API key.",
            model_used=None,
            error_message=None,
        )

    model = model_name or os.getenv("GEMINI_MODEL", "gemini-2.5-flash")

    # Truncate resume text to keep token usage lean and avoid timeouts
    safe_text = (candidate_text or "")[:10000].strip()
    matched_str = ", ".join(matched_skills) if matched_skills else "None explicitly extracted"
    missing_str = ", ".join(missing_skills) if missing_skills else "None"

    prompt = f"""You are an expert technical recruiting advisor. Your job is to objectively validate a candidate's resume against a job description, identify real-world technical credibility, highlight strengths and risks, and provide tailored technical interview questions.

TARGET JOB DESCRIPTION:
\"\"\"{job_description}\"\"\"

CANDIDATE INFORMATION:
Candidate Identifier: {candidate_name}
Confirmed Matched Skills: {matched_str}
Identified Missing Skills: {missing_str}

RESUME EXTRACTED CONTENT:
\"\"\"{safe_text if safe_text else "(No full resume text provided; evaluate based on extracted skill taxonomy)"}\"\"\"

EVALUATION CRITERIA:
1. validation_score: An integer between 0 and 100 representing technical depth, project authenticity, and role alignment.
2. executive_summary: 2-3 sentences providing an executive summary of candidate fit for this specific job.
3. strengths: 2-4 concise bullet points highlighting concrete achievements or skills relevant to the role.
4. risks_or_concerns: 1-3 bullet points identifying gaps, buzzword claims lacking project context, or areas needing verification.
5. interview_questions: 2-3 specific technical interview questions tailored to verify their project depth or address missing skills.
6. authenticity_assessment: 1 clear sentence assessing whether the resume demonstrates genuine hands-on technical substance.

Respond ONLY with a valid JSON object matching this schema:
{{
  "validation_score": 85,
  "executive_summary": "...",
  "strengths": ["...", "..."],
  "risks_or_concerns": ["..."],
  "interview_questions": ["...", "..."],
  "authenticity_assessment": "..."
}}
"""

    try:
        from google import genai
        from google.genai import types

        client = genai.Client(api_key=api_key)

        response = client.models.generate_content(
            model=model,
            contents=prompt,
            config=types.GenerateContentConfig(
                response_mime_type="application/json",
                temperature=0.2,
            ),
        )

        response_text = response.text or ""
        cleaned_json = _clean_json_markdown(response_text)
        data = json.loads(cleaned_json)

        return GeminiValidationResult(
            status="success",
            validation_score=int(data.get("validation_score", 75)),
            executive_summary=str(data.get("executive_summary", "Fit evaluated by Gemini AI.")),
            strengths=list(data.get("strengths", [])),
            risks_or_concerns=list(data.get("risks_or_concerns", [])),
            interview_questions=list(data.get("interview_questions", [])),
            authenticity_assessment=str(
                data.get("authenticity_assessment", "Technical profile validated.")
            ),
            model_used=model,
            error_message=None,
        )

    except Exception as exc:
        logger.warning("Gemini resume validation failed: %s", exc, exc_info=True)
        return GeminiValidationResult(
            status="error",
            validation_score=None,
            executive_summary=(
                "Gemini AI validation encountered an error during processing. "
                "Deterministic evaluation results remain unaffected."
            ),
            strengths=matched_skills[:3] if matched_skills else [],
            risks_or_concerns=(
                [f"Missing skills: {', '.join(missing_skills[:3])}"]
                if missing_skills
                else []
            ),
            interview_questions=[],
            authenticity_assessment="Unable to complete AI validation due to provider error.",
            model_used=model,
            error_message=str(exc),
        )
